
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>NSBM SportsVerse</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="assets/tailwind.css">
<style>
  body { background:#0B132B; }
  .card { background:#1C2541; border:1px solid #2E3B63; border-radius:16px; }
  .slot:focus-visible, .btn:focus-visible, a:focus-visible { outline:2px solid #3DD6A0; outline-offset:2px; }
  .pulse { animation: pulse 1.4s ease-in-out infinite; }
  @keyframes pulse { 50% { opacity:.3; } }
  @media (prefers-reduced-motion: reduce) { .pulse { animation:none; } }

  .hero-reveal { animation: reveal 1.2s cubic-bezier(.77,0,.18,1) both; }
  @keyframes reveal { from { clip-path: inset(46% 0 46% 0); } to { clip-path: inset(0 0 0 0); } }
  .hero-img { animation: zoomIn 1.8s cubic-bezier(.2,.7,.2,1) both, kb 22s ease-in-out 1.8s infinite alternate; }
  @keyframes zoomIn { from { transform: scale(1.4); } to { transform: scale(1); } }
  @keyframes kb { from { transform: scale(1); } to { transform: scale(1.12) translateX(-1.5%); } }
  .hero-shine { background: linear-gradient(105deg, transparent 40%, rgba(61,214,160,.22) 50%, transparent 60%); transform: translateX(-120%); animation: shine 9s ease-in-out 2.2s infinite; }
  @keyframes shine { 0% { transform: translateX(-120%); } 20%, 100% { transform: translateX(120%); } }
  .word { display: inline-block; opacity: 0; filter: blur(10px); transform: translateY(28px); animation: wordIn .9s cubic-bezier(.2,.7,.2,1) forwards; animation-delay: calc(.7s + var(--i) * .13s); }
  @keyframes wordIn { to { opacity: 1; filter: blur(0); transform: none; } }
  .fade { opacity: 0; animation: fadeUp .8s cubic-bezier(.2,.7,.2,1) forwards; animation-delay: var(--d); }
  @keyframes fadeUp { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
  .chip { opacity: 0; animation: chipIn .7s cubic-bezier(.2,.7,.2,1) forwards var(--d), floaty 5s ease-in-out infinite alternate calc(var(--d) + .7s); }
  @keyframes chipIn { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: none; } }
  @keyframes floaty { to { transform: translateY(-5px); } }
  .cta-ring { animation: ring 2.4s ease-out 2.2s infinite; }
  @keyframes ring { 0% { box-shadow: 0 0 0 0 rgba(15,138,95,.6); } 70%, 100% { box-shadow: 0 0 0 14px rgba(15,138,95,0); } }
  @media (prefers-reduced-motion: reduce) {
    .hero-reveal, .hero-img, .word, .fade, .chip, .cta-ring { animation: none !important; }
    .word, .fade, .chip { opacity: 1; filter: none; transform: none; } .hero-shine { display: none; }
  }

  .logo-anim { --logo: url("data:image/png;base64,"); position: relative; display: block; aspect-ratio: 2.2246; }
  .logo-anim > div, .logo-anim .lg-iw > div { position: absolute; inset: 0; background: var(--logo) center / 100% 100% no-repeat; }
  .lg-iw { position: absolute; inset: 0; transform-origin: 17% 55%; transition: transform .35s cubic-bezier(.34,1.56,.64,1); }
  .logo-link:hover .lg-iw { transform: rotate(-7deg) scale(1.08); }
  .lg-icon { clip-path: inset(0 64.8% 0 0); transform-origin: 17% 55%; animation: lgPop 1s cubic-bezier(.34,1.56,.64,1) both; }
  .lg-text { clip-path: inset(0 0 0 35.2%); animation: lgText 1s cubic-bezier(.2,.7,.2,1) .35s both; }
  .lg-shine { -webkit-mask: var(--logo) center / 100% 100% no-repeat; mask: var(--logo) center / 100% 100% no-repeat; background: linear-gradient(105deg, transparent 38%, rgba(255,255,255,.9) 50%, transparent 62%) !important; background-size: 260% 100% !important; background-position: 160% 0 !important; animation: lgShine 7s ease-in-out 1.8s infinite; pointer-events: none; }
  @keyframes lgPop { from { opacity: 0; transform: scale(.4) rotate(-18deg); } to { opacity: 1; transform: none; } }
  @keyframes lgText { from { opacity: 0; transform: translateX(-26px); } to { opacity: 1; transform: none; } }
  @keyframes lgShine { 0% { background-position: 160% 0; } 22%, 100% { background-position: -60% 0; } }
  @media (prefers-reduced-motion: reduce) { .lg-icon, .lg-text, .lg-shine { animation: none; } .lg-shine { display: none; } .lg-iw { transition: none; } }
</style>
</head>
<body class="font-sans text-slate-200 min-h-screen">

<!-- Navigation -->
<header class="sticky top-0 z-20 bg-ink/90 backdrop-blur border-b border-line">
  <div class="max-w-7xl mx-auto px-4 h-24 flex items-center gap-6">
    <a href="#home" class="logo-link flex items-center gap-3 shrink-0" aria-label="NSBM SportsVerse">
      <span class="logo-anim h-16 sm:h-20" role="img" aria-label="NSBM Green University Town">
        <span class="lg-iw"><div class="lg-icon"></div></span><div class="lg-text"></div><div class="lg-shine"></div>
      </span>
      <span class="hidden sm:block font-bold text-white text-lg border-l border-line pl-3">Sports<span class="text-mint">Verse</span></span>
    </a>
    <nav class="hidden lg:flex items-center gap-1 text-sm">
      <a href="#home" data-tab="home" class="px-3 py-2 rounded-lg text-slate-400 hover:text-white hover:bg-card">Home</a>
      <a href="#clubs" data-tab="clubs" class="px-3 py-2 rounded-lg text-slate-400 hover:text-white hover:bg-card">Clubs</a>
      <a href="#matches" data-tab="matches" class="px-3 py-2 rounded-lg text-slate-400 hover:text-white hover:bg-card">Matches</a>
      <a href="#tournaments" data-tab="tournaments" class="px-3 py-2 rounded-lg text-slate-400 hover:text-white hover:bg-card">Tournaments</a>
      <a href="#leaderboard" data-tab="leaderboard" class="px-3 py-2 rounded-lg text-slate-400 hover:text-white hover:bg-card">Leaderboard</a>
      <a href="#facilities" data-tab="facilities" class="px-3 py-2 rounded-lg text-slate-400 hover:text-white hover:bg-card">Facilities</a>
    </nav>
    <div id="authArea" class="ml-auto flex items-center gap-2"></div>
  </div>
  <nav class="lg:hidden flex gap-1 overflow-x-auto px-4 pb-2 text-sm">
      <a href="#home" data-tab="home" class="shrink-0 whitespace-nowrap px-3 py-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-card">Home</a>
      <a href="#clubs" data-tab="clubs" class="shrink-0 whitespace-nowrap px-3 py-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-card">Clubs</a>
      <a href="#matches" data-tab="matches" class="shrink-0 whitespace-nowrap px-3 py-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-card">Matches</a>
      <a href="#tournaments" data-tab="tournaments" class="shrink-0 whitespace-nowrap px-3 py-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-card">Tournaments</a>
      <a href="#leaderboard" data-tab="leaderboard" class="shrink-0 whitespace-nowrap px-3 py-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-card">Leaderboard</a>
      <a href="#facilities" data-tab="facilities" class="shrink-0 whitespace-nowrap px-3 py-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-card">Facilities</a>
  </nav>
</header>

<main class="max-w-7xl mx-auto px-4 py-6">
<div id="view-home" class="view grid gap-6 lg:grid-cols-3">
<section id="hero" class="relative lg:col-span-3 h-80 sm:h-[30rem] rounded-2xl overflow-hidden border border-line bg-ink" aria-label="NSBM rugby team">
  <div class="hero-reveal absolute inset-0">
    <div id="heroParallax" class="absolute -inset-[6%] will-change-transform">
      <img src="Home-Rugby.jpg" alt="NSBM rugby team celebrating on the pitch with one player lifted high" class="hero-img w-full h-full object-cover" style="object-position:50% 20%">
</div>
  <div class="hero-shine absolute inset-0 pointer-events-none" aria-hidden="true"></div>
  <div class="absolute inset-0 bg-gradient-to-t from-ink via-ink/35 to-transparent"></div>
  <div class="absolute inset-0 bg-gradient-to-r from-ink/85 via-ink/30 to-transparent"></div>
  <div class="absolute right-4 top-4 sm:right-6 sm:top-6 flex flex-col items-end gap-2">
    <span class="chip bg-ink/55 backdrop-blur border border-white/15 rounded-full px-3.5 py-1.5 text-xs sm:text-sm text-white" style="--d:1.3s"><b id="heroMembers" class="text-mint tabular-nums" data-count="0">0</b> members</span>
    <span class="chip bg-ink/55 backdrop-blur border border-white/15 rounded-full px-3.5 py-1.5 text-xs sm:text-sm text-white" style="--d:1.5s"><span id="heroTrain">Join the squad</span></span>
  </div>
  <div class="absolute left-5 bottom-5 sm:left-8 sm:bottom-8 max-w-lg">
    <h1 class="sr-only">NSBM Rugby Team</h1>
    <p class="fade text-white text-lg sm:text-2xl font-semibold" style="--d:1.3s">Follow the squad's matches and join training.</p>
    <a href="#clubs" class="fade cta-ring btn inline-block mt-3 rounded-xl bg-em hover:bg-emerald-700 text-white font-medium px-5 py-2.5 text-sm" style="--d:1.6s">Join the team</a>
  </div>
</section>

<section data-live class="card p-5 lg:col-span-3 hidden" aria-label="Live match"></section>
<section id="passport" class="card p-5" aria-label="My Sports Passport"></section>
<div class="lg:col-span-2 grid gap-6 content-start">
  <section class="card p-5" aria-label="Quick actions">
    <h2 class="font-semibold text-white mb-4">Quick actions</h2>
    <div class="grid sm:grid-cols-2 gap-3">
      <a href="#facilities" class="btn rounded-xl bg-em hover:bg-emerald-700 text-white font-medium py-3 flex items-center justify-center gap-2">
        <svg viewBox="0 0 24 24" class="w-5 h-5" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/></svg>Book court</a>
      <a href="#clubs" class="btn rounded-xl border border-mint text-mint hover:bg-mint/10 font-medium py-3 flex items-center justify-center gap-2">
        <svg viewBox="0 0 24 24" class="w-5 h-5" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="8" r="4"/><path d="M2 21c0-4 3-6 7-6s7 2 7 6M19 8v6M16 11h6"/></svg>Join club</a>
    </div>
  </section>
  <section class="card p-5" aria-label="Upcoming matches">
    <div class="flex items-center justify-between mb-3"><h2 class="font-semibold text-white">Upcoming matches</h2><a href="#matches" class="text-sm text-mint hover:underline">See all</a></div>
    <div id="home-upcoming" class="divide-y divide-line"></div>
  </section>
</div>
</div>
<div id="view-clubs" class="view hidden ">
<div class="mb-5"><h1 class="text-2xl font-semibold text-white">Clubs</h1><p class="text-sm text-slate-400 mt-1">Find a club, check its schedule, and join in one tap.</p></div>
<div class="flex flex-col md:flex-row gap-3 mb-5">
  <label class="relative md:w-72 shrink-0"><span class="sr-only">Search clubs</span>
    <svg viewBox="0 0 24 24" class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>
    <input id="clubSearch" type="search" placeholder="Search clubs or sports" class="w-full bg-card border border-line rounded-xl pl-9 pr-3 py-2.5 text-sm placeholder:text-slate-500 focus:outline-none focus:border-mint"></label>
  <div id="clubChips" class="flex gap-2 overflow-x-auto pb-1" role="group" aria-label="Filter clubs"></div>
</div>
<div id="club-grid" class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4"></div>
<div id="club-empty" class="hidden card p-10 text-center"><p class="text-white font-medium">No clubs match your search</p><p class="text-sm text-slate-400 mt-1">Try another sport or clear the filters.</p><button id="clubClear" class="btn mt-4 rounded-xl border border-mint text-mint hover:bg-mint/10 px-5 py-2 text-sm">Clear filters</button></div>
</div>
<div id="view-matches" class="view hidden ">
<div class="mb-5"><h1 class="text-2xl font-semibold text-white">Matches</h1><p class="text-sm text-slate-400 mt-1">Follow live games, plan what to watch, and check results.</p></div><div class="grid gap-6">
<section data-live class="card p-5 hidden" aria-label="Live match"></section>
<section class="card p-5" aria-label="Match list">
  <div class="flex flex-col md:flex-row md:items-center justify-between gap-3 mb-4">
    <div id="mSeg" class="inline-flex self-start rounded-xl bg-ink border border-line p-1" role="tablist"></div>
    <div id="mChips" class="flex gap-2 overflow-x-auto pb-1" role="group" aria-label="Filter by sport"></div>
  </div>
  <div id="mList" class="grid md:grid-cols-2 gap-3"></div>
</section></div>
</div>
<div id="view-tournaments" class="view hidden ">
<div class="mb-5"><h1 class="text-2xl font-semibold text-white">Tournaments</h1><p id="tournamentSub" class="text-sm text-slate-400 mt-1">Knockout brackets and fixtures</p></div>
<div id="tournamentRoot"></div>
</div>
<div id="view-leaderboard" class="view hidden ">
<div class="mb-5"><h1 class="text-2xl font-semibold text-white">Leaderboard</h1><p class="text-sm text-slate-400 mt-1">See who is leading and how far you are from the podium.</p></div>
<div class="flex flex-col md:flex-row md:items-center justify-between gap-3 mb-5">
  <div id="lbSeg" class="inline-flex self-start rounded-xl bg-ink border border-line p-1" role="tablist"></div>
  <div id="lbChips" class="flex gap-2 overflow-x-auto pb-1" role="group" aria-label="Filter by sport"></div>
</div>
<div class="grid gap-6 lg:grid-cols-2 content-start">
  <div class="grid gap-6 content-start">
    <section class="card p-5" aria-label="Top three"><div id="podium" class="grid grid-cols-3 gap-3 items-end max-w-md mx-auto"></div></section>
    <section id="lbYou" class="card p-5" aria-label="Your position"></section>
  </div>
  <section class="card p-5" aria-label="Full rankings"><h2 class="font-semibold text-white mb-2">Full rankings</h2><ol id="rank-list" class="divide-y divide-line"></ol></section>
</div>
</div>
<div id="view-facilities" class="view hidden grid gap-6 lg:grid-cols-2 content-start">
<section id="booking" class="card p-5" aria-label="Book a facility">
  <h2 class="font-semibold text-white">Book a facility</h2>
  <p class="text-sm text-slate-400 mt-1">Pick a facility, a date and a time. An admin approves each request.</p>
  <div class="mt-4 grid sm:grid-cols-2 gap-3">
    <label class="text-xs text-slate-400">Facility
      <select id="court" class="mt-1 w-full bg-ink border border-line rounded-lg text-sm text-white px-2 py-2"></select></label>
    <label class="text-xs text-slate-400">Date
      <input id="bdate" type="date" class="mt-1 w-full bg-ink border border-line rounded-lg text-sm text-white px-2 py-2"></label>
  </div>
  <div class="mt-4 text-sm font-medium text-white">Pick a time</div>
  <div id="slots" class="mt-3 grid grid-cols-2 sm:grid-cols-3 gap-2 text-sm"></div>
  <div class="mt-3 flex gap-4 text-xs text-slate-400">
    <span class="flex items-center gap-1.5"><i class="w-3 h-3 rounded bg-ink border border-line"></i>Open</span>
    <span class="flex items-center gap-1.5"><i class="w-3 h-3 rounded bg-em"></i>Selected</span>
    <span class="flex items-center gap-1.5"><i class="w-3 h-3 rounded bg-slate-700"></i>Booked</span>
  </div>
  <button id="confirm" disabled class="btn mt-4 w-full rounded-xl bg-em text-white font-medium py-2.5 disabled:bg-slate-700 disabled:text-slate-400 disabled:cursor-not-allowed">Select a time to continue</button>
  <p id="toast" class="mt-3 text-sm text-mint hidden" role="status"></p>
  <h3 class="mt-6 text-sm font-medium text-white">My booking requests</h3>
  <div id="myBookings" class="mt-2 divide-y divide-line"></div>
</section>
<section class="card p-5" aria-label="Facilities"><h2 class="font-semibold text-white mb-3">Campus facilities</h2><div id="fac-list" class="divide-y divide-line"></div></section>
</div>
</main>

<div id="gtoast" role="status" class="fixed bottom-5 left-1/2 -translate-x-1/2 z-30 px-4 py-2.5 rounded-xl bg-em text-white text-sm shadow-lg opacity-0 translate-y-4 transition pointer-events-none"></div>
<div id="authModal" class="hidden fixed inset-0 z-40 bg-black/60 backdrop-blur-sm grid place-items-center p-4" role="dialog" aria-modal="true" aria-labelledby="authTitle">
  <form id="authForm" class="card w-full max-w-sm p-6 relative" autocomplete="on">
    <button type="button" id="authClose" class="btn absolute right-3 top-3 w-8 h-8 rounded-lg text-slate-400 hover:text-white" aria-label="Close">✕</button>
    <h2 id="authTitle" class="text-xl font-semibold text-white">Log in</h2>
    <div class="mt-4 grid gap-3">
      <label data-reg class="hidden text-xs text-slate-400">Full name<input id="f_name" class="mt-1 w-full bg-ink border border-line rounded-lg text-sm text-white px-3 py-2" autocomplete="name"></label>
      <label data-reg class="hidden text-xs text-slate-400">Student ID<input id="f_sid" class="mt-1 w-full bg-ink border border-line rounded-lg text-sm text-white px-3 py-2" placeholder="e.g. STU123"></label>
      <label class="text-xs text-slate-400">Email<input id="f_email" type="email" required class="mt-1 w-full bg-ink border border-line rounded-lg text-sm text-white px-3 py-2" autocomplete="email"></label>
      <label class="text-xs text-slate-400">Password<input id="f_pass" type="password" required minlength="6" class="mt-1 w-full bg-ink border border-line rounded-lg text-sm text-white px-3 py-2" autocomplete="current-password"></label>
    </div>
    <p id="authErr" class="mt-3 text-sm text-red-300 min-h-[1.25rem]" role="alert"></p>
    <button id="authSubmit" class="btn mt-2 w-full rounded-xl bg-em hover:bg-emerald-700 text-white font-medium py-2.5">Log in</button>
    <p id="authSwitch" class="mt-4 text-sm text-slate-400 text-center"></p>
    <p id="authDemo" class="mt-3 text-xs text-slate-500 text-center">Demo: kamal@example.com / student123 &middot; admin@example.com / admin123</p>
  </form>
</div>
<script src="assets/app.js"></script>
</body>
</html>
